(6225969, 920341, 108580, '<td valign="top">Tablemountain and Signal Hill in the BG :) The creative perspective is understandable to get it all, perhaps too much as it is very tiring to look at for long. It hasn''t got that edge I think it needs to be really punchy. The near midday sun has also made lighting harsh.</td>', 'Tablemountain and Signal Hill in the BG :) The creative perspective is understandable to get it all, perhaps too much as it is very tiring to look at for long. It hasn''t got that edge I think it needs to be really punchy. The near midday sun has also made lighting harsh.', '2010-11-17 13:59:28.000000', NULL, 1),
(6225976, 919954, 108580, '<td valign="top">Well spotted, in terms of the "Military <u>In Nature</u>" angle.</td>', 'Well spotted, in terms of the "Military In Nature" angle.', '2010-11-17 14:08:14.000000', NULL, 1),
(6225979, 920304, 108580, '<td valign="top">Great image, good perspective and processing. Love the grain and DOF.</td>', 'Great image, good perspective and processing. Love the grain and DOF.', '2010-11-17 14:11:17.000000', NULL, 1),
(6225996, 920341, 99263, '<td valign="top">Nice shot with Table mountain in the background.</td>', 'Nice shot with Table mountain in the background.', '2010-11-17 14:26:09.000000', NULL, 1),
