(6226007, 920459, 108580, '<td valign="top">...and a page from the cover of a U2 album. Nicely done.</td>', '...and a page from the cover of a U2 album. Nicely done.', '2010-11-17 14:31:42.000000', NULL, 1),
(6226012, 919718, 108580, '<td valign="top">Nice perspective and DOF control. <br/>But the FD is not a military organisation. We didn''t run around armed with anything more than a hose and a branch (firefighting nozzle). You may get military based FD''s or serviceman who perform that role. I''m not robbing you of points for this however.</td>', 'Nice perspective and DOF control. But the FD is not a military organisation. We didn''t run around armed with anything more than a hose and a branch (firefighting nozzle). You may get military based FD''s or serviceman who perform that role. I''m not robbing you of points for this however.', '2010-11-17 14:36:49.000000', NULL, 1),
(6226015, 920447, 108580, '<td valign="top">Nicely candid. This is one of those images that could do with a lot of grain, especially as you have chosen a more off grey to sepia tone than pure B&amp;W. The tent tie (cable) is running straight through his head via the mouth.</td>', 'Nicely candid. This is one of those images that could do with a lot of grain, especially as you have chosen a more off grey to sepia tone than pure B&W. The tent tie (cable) is running straight through his head via the mouth.', '2010-11-17 14:40:52.000000', NULL, 1),
(6226033, 919911, 99263, '<td valign="top">Very nice angle and processing give a dramatic view of the angel on the Anglo-Boer War Memorial at the South African National Museum of Military History in Johannesburg.</td>', 'Very nice angle and processing give a dramatic view of the angel on the Anglo-Boer War Memorial at the South African National Museum of Military History in Johannesburg.', '2010-11-17 14:54:00.000000', NULL, 1),
(6226039, 919984, 99263, '<td valign="top">I like the extreme angle and processing.</td>', 'I like the extreme angle and processing.', '2010-11-17 14:56:02.000000', NULL, 1),
(6226079, 919482, 43774, '<td valign="top">Looks like the war memorial in St. John''s.</td>', 'Looks like the war memorial in St. John''s.', '2010-11-17 15:39:37.000000', NULL, 1),
(6226119, 920450, 115307, '<td valign="top">This has got to be a ribbon. Fantastic stuff. 10 from me.<br/>Better than stuff I have seen in National Geographic</td>', 'This has got to be a ribbon. Fantastic stuff. 10 from me.Better than stuff I have seen in National Geographic', '2010-11-17 16:16:27.000000', NULL, 1),
