(6226410, 920341, 4793, '<td valign="top">Nice work</td>', 'Nice work', '2010-11-17 20:23:05.000000', NULL, 1),
(6226412, 920418, 108069, '<td valign="top">Lovely light. Excellent shadows. Wonderful tones. Truly remarkable clarity throughout the entire image. Ever single stone is razor sharp. Outstanding photo and certainly one of the best.</td>', 'Lovely light. Excellent shadows. Wonderful tones. Truly remarkable clarity throughout the entire image. Ever single stone is razor sharp. Outstanding photo and certainly one of the best.', '2010-11-17 20:24:17.000000', NULL, 1),
(6226416, 920241, 4793, '<td valign="top">Nice photo</td>', 'Nice photo', '2010-11-17 20:26:20.000000', NULL, 1),
(6226525, 920312, 96751, '<td valign="top">awesome!  Would not have thought of military from another century!</td>', 'awesome!  Would not have thought of military from another century!', '2010-11-17 22:05:56.000000', NULL, 1),
(6226527, 919907, 96751, '<td valign="top">This would also have worked in reflections, although I suspect this was a strategic choice :-)  Beautiful and moving.</td>', 'This would also have worked in reflections, although I suspect this was a strategic choice :-)  Beautiful and moving.', '2010-11-17 22:07:03.000000', NULL, 1),
(6226530, 920328, 96751, '<td valign="top">incredible candid moment.</td>', 'incredible candid moment.', '2010-11-17 22:07:19.000000', NULL, 1),
(6226532, 920198, 96751, '<td valign="top">So moody and quiet.  Very subtle on many levels, but eloquent as well.</td>', 'So moody and quiet.  Very subtle on many levels, but eloquent as well.', '2010-11-17 22:08:02.000000', NULL, 1),
(6226537, 919438, 96751, '<td valign="top">Oh how wonderful.  A couple of inches to the right and you would have had a perfectly symmetrical image.  Love the muted colors, and the surprise of the red.  Front page.</td>', 'Oh how wonderful.  A couple of inches to the right and you would have had a perfectly symmetrical image.  Love the muted colors, and the surprise of the red.  Front page.', '2010-11-17 22:09:23.000000', NULL, 1),
(6226538, 920193, 96751, '<td valign="top">One of the most unique entries on DPC.</td>', 'One of the most unique entries on DPC.', '2010-11-17 22:09:58.000000', NULL, 1),
(6226539, 920304, 96751, '<td valign="top">Awesome in monochrome.</td>', 'Awesome in monochrome.', '2010-11-17 22:10:15.000000', NULL, 1),
(6226540, 920459, 96751, '<td valign="top">Though very dark, the darkness adds a sense of history and nostalgia.  Wonderful portrait.</td>', 'Though very dark, the darkness adds a sense of history and nostalgia.  Wonderful portrait.', '2010-11-17 22:10:51.000000', NULL, 1),
(6226541, 919775, 96751, '<td valign="top">LOL!!!!!!!!!!!!!!!!!!!!!!!!!1</td>', 'LOL!!!!!!!!!!!!!!!!!!!!!!!!!1', '2010-11-17 22:11:05.000000', NULL, 1),
(6226542, 919718, 96751, '<td valign="top">Fabulous pov, and the water drops on his visor are a delicious detail.  Nicely caught.</td>', 'Fabulous pov, and the water drops on his visor are a delicious detail.  Nicely caught.', '2010-11-17 22:11:45.000000', NULL, 1),
(6226544, 920241, 96751, '<td valign="top">I''m so glad your title explained what we are witnessing.  I was gonna get all riled up :-)</td>', 'I''m so glad your title explained what we are witnessing.  I was gonna get all riled up :-)', '2010-11-17 22:12:55.000000', NULL, 1),
(6226545, 919954, 96751, '<td valign="top">Nice shoehorm :-)</td>', 'Nice shoehorm :-)', '2010-11-17 22:13:12.000000', NULL, 1),
(6226547, 920450, 96751, '<td valign="top">Great color choice.  Adds to the sense of action.</td>', 'Great color choice.  Adds to the sense of action.', '2010-11-17 22:13:53.000000', NULL, 1),
(6226549, 919911, 96751, '<td valign="top">What an intense and foreboding sky.  I really like how the angel is highlighted (there IS a positive side to pigeon droppings!!!), and how the complexity of the statue is underscored by the strong but simple lines of the monument.</td>', 'What an intense and foreboding sky.  I really like how the angel is highlighted (there IS a positive side to pigeon droppings!!!), and how the complexity of the statue is underscored by the strong but simple lines of the monument.', '2010-11-17 22:14:58.000000', NULL, 1),
(6226550, 920418, 96751, '<td valign="top">Very moving in b/w.</td>', 'Very moving in b/w.', '2010-11-17 22:15:23.000000', NULL, 1),
(6226679, 919531, 40391, '<td valign="top">SAM... wasn''t that the same name as the sheep dog that protected the flock from the wolf in a popular cartoon many moons ago? But I''m showing my age though it still shows something formable out there protecting it''s flock.<br/> <br/>Nice sharp focus on the weapon without loosing too much detail on the background - but enough to make your subject pop.  The photo on a whole tells an interesting story that I don''t know but can imagine.  Overall, I quite like this - 7.</td>', 'SAM... wasn''t that the same name as the sheep dog that protected the flock from the wolf in a popular cartoon many moons ago? But I''m showing my age though it still shows something formable out there protecting it''s flock. Nice sharp focus on the weapon without loosing too much detail on the background - but enough to make your subject pop.  The photo on a whole tells an interesting story that I don''t know but can imagine.  Overall, I quite like this - 7.', '2010-11-18 01:21:32.000000', NULL, 1),
