(6230211, 920398, 76335, '<td valign="top">What reach the wide angle gives it! Backlighting was a nice touch as are the ominous cloud and the two trees bowing to it. Excellent.</td>', 'What reach the wide angle gives it! Backlighting was a nice touch as are the ominous cloud and the two trees bowing to it. Excellent.', '2010-11-22 17:52:08.000000', NULL, 1),
(6230212, 920275, 76335, '<td valign="top">Intense, sincere.</td>', 'Intense, sincere.', '2010-11-22 17:52:34.000000', NULL, 1),
(6230214, 920329, 76335, '<td valign="top">The swirling chaotic rhythm, the drab monochrome treatment, the sharpness which goes in and out of focus -- all very effective. Certainly nothing I want to get tangled up in.</td>', 'The swirling chaotic rhythm, the drab monochrome treatment, the sharpness which goes in and out of focus -- all very effective. Certainly nothing I want to get tangled up in.', '2010-11-22 17:56:57.000000', NULL, 1),
(6230216, 920304, 76335, '<td valign="top">So young. The shallow DOF and grain are effective, of course. But for me, it''s that struggling flower that turns this into poetry.</td>', 'So young. The shallow DOF and grain are effective, of course. But for me, it''s that struggling flower that turns this into poetry.', '2010-11-22 17:59:00.000000', NULL, 1);
